package tv.vela.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.media.MediaPlayer;import android.view.*;import android.widget.*;import android.graphics.Bitmap;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Direct public M3U integration on an isolated emulator. Restores the chosen source. */
public final class AndroidLiveTvTest extends Instrumentation {
 private interface Ready{boolean ready()throws Exception;}
 private Object field(Object o,String name)throws Exception{if(o instanceof ScreenActivity)o=((ScreenActivity)o).screen;for(Class<?> type=o.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
 private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private void await(Ready r,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){waitForIdleSync();if(r.ready())return;Thread.sleep(100);}throw new AssertionError(message);}
 private void shot(Context c,String name)throws Exception{waitForIdleSync();Thread.sleep(500);Bitmap b=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 private void restore(SharedPreferences prefs,Map<String,?> saved){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> entry:saved.entrySet()){Object v=entry.getValue();String k=entry.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<>((Set<String>)v));}e.commit();}
 private void playerLayout(LiveTvPlayer p,Bundle result)throws Exception{View stage=(View)field(p,"stage"),panel=(View)field(p,"panel");android.graphics.Rect rect=new android.graphics.Rect();panel.getGlobalVisibleRect(rect);check(stage.getWidth()==p.getWidth()&&stage.getHeight()==p.getHeight()&&stage.getScaleX()==1&&stage.getScaleY()==1,"Player uses a clipped scaled render layer");check(rect.right==p.getWidth()&&rect.bottom==p.getHeight(),"Player shade does not span the viewport");result.putString("player_layout","PASS native viewport controls and full-width shade at "+p.getWidth()+"x"+p.getHeight());}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences prefs=LiveTvData.prefs(c);Map<String,?> saved=new HashMap<>(prefs.getAll());Map<String,?> plex=new HashMap<>(new PlexClient(c).prefs.getAll());LiveTvActivity activity=null;Activity settings=null;try{
  Locale.setDefault(new Locale("es","ES"));
  check(android.os.Build.MODEL.contains("sdk")||android.os.Build.FINGERPRINT.contains("generic"),"Isolated emulator required");
  M3uClient client=new M3uClient(c);client.configure(LiveTvData.DEFAULT_M3U,"",false);prefs.edit().putInt("tv-page-"+LiveTvData.hash(LiveTvData.source(c)),0).putString("tv-group-"+LiveTvData.hash(LiveTvData.source(c)),"@all").commit();client.refresh(true);TvCatalogCache.Page page=client.page(null,"",null,0);check(page.total>100&&page.channels.size()==12,"Public direct M3U did not load");for(LiveTvData.Channel channel:page.channels)check(channel.playable(),"Non-direct entry included");
  activity=(LiveTvActivity)startActivitySync(new Intent(c,LiveTvActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));LiveTvActivity tv=activity;await(()->tv.catalog!=null&&!(Boolean)field(tv,"loading"),"Native M3U browser did not load");await(()->!((Map<?,?>)field(tv,"guide")).isEmpty(),"Real visible programme guide missing");await(()->{for(ImageView image:(List<ImageView>)field(tv,"images"))if(image.getDrawable()!=null)return true;return false;},"Original channel logos missing");Thread.sleep(5000);shot(c,"live-tv-channels.png");Method sources=LiveTvActivity.class.getDeclaredMethod("showSources");sources.setAccessible(true);ui(()->{try{sources.invoke(tv);}catch(Exception failure){throw new RuntimeException(failure);}});shot(c,"live-tv-sources.png");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();
  LiveTvData.Channel direct=null;for(int i=0;i<Math.min(10,(page.total+11)/12);i++){for(LiveTvData.Channel channel:client.page(null,"",null,i).channels)if(channel.epgId.equals("La1.TV"))direct=channel;if(direct!=null)break;}check(direct!=null,"Public direct RTVE signal missing");LiveTvData.Channel chosen=direct;ui(()->tv.play(chosen));await(()->tv.playback!=null&&tv.playback.rendered,"Real live signal did not decode");LiveTvPlayer video=tv.playback;MediaPlayer nativePlayer=video.player;check(nativePlayer.isPlaying()&&nativePlayer.getVideoWidth()>0,"No native video");int before=nativePlayer.getCurrentPosition();Thread.sleep(1500);check(nativePlayer.getCurrentPosition()>before,"Live signal did not advance");result.putInt("decoded_width",nativePlayer.getVideoWidth());playerLayout(video,result);shot(c,"live-tv-player.png");
  settings=startActivitySync(new Intent(c,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->video.player==null&&!video.active,"Leaving retained decoder/audio");Activity over=settings;ui(over::finish);settings=null;await(()->tv.playback!=null&&tv.playback.rendered,"Native resume failed");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();check(tv.playback==null,"Back retained decoder");
  check(plex.equals(new PlexClient(c).prefs.getAll()),"TV changed Plex account");result.putInt("public_direct_channels",page.total);result.putString("result","PASS actual public M3U, indexed twelve-row pages, original logos, real now/next guide, decoded and advancing official live video, pause/release/resume, Back to channels. No website player or third-party IPTV app. Preferences restored.");
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(settings!=null){Activity a=settings;ui(a::finish);}if(activity!=null){LiveTvActivity a=activity;ui(a::finish);}restore(prefs,saved);}finish(result.containsKey("error")?1:-1,result);}
}
